def c021():
    import heapq
    graph = {"A": [("B", 2), ("C", 3)], "B": [], "C": [("B", -2)]}

    def dijkstra(src):
        dist = {v: float("inf") for v in graph}
        dist[src] = 0
        settled = set()
        pq = [(0, src)]
        while pq:
            d, u = heapq.heappop(pq)
            if u in settled:
                continue
            settled.add(u)
            for v, w in graph[u]:
                if v not in settled and d + w < dist[v]:
                    dist[v] = d + w
                    heapq.heappush(pq, (dist[v], v))
        return dist

    def bellman_ford(src):
        dist = {v: float("inf") for v in graph}
        dist[src] = 0
        for _ in range(len(graph) - 1):
            for u in graph:
                for v, w in graph[u]:
                    if dist[u] + w < dist[v]:
                        dist[v] = dist[u] + w
        return dist
    return dijkstra("A") == bellman_ford("A")


