def c025():
    coins = [4, 3, 1]

    def greedy(n):
        c = 0
        for coin in coins:
            c += n // coin
            n %= coin
        return c

    def best(n):
        dp = [0] + [10 ** 9] * n
        for v in range(1, n + 1):
            dp[v] = min(dp[v - c] + 1 for c in coins if c <= v)
        return dp[n]
    return all(greedy(n) == best(n) for n in range(1, 101))


